entries[150734] = { ["name"] = "Luftangriff", ["text"] = "Benutzen: Schließt sofort eine Weltquest an der Brachlandkriegsfront ab." }
entries[150735] = { ["name"] = "Mondbeere", ["text"] = "Einzigartig (5)\nBenutzen: Füttert Euer Mondkinküken, um es glücklich zu machen.\nBenötigt Mondkinfest\n\"Beerenlecker.\"\nVerkaufspreis:" }
entries[150736] = { ["name"] = "Fallschirmjäger", ["text"] = "Benutzen: Lässt Marinesoldaten der 7. Flotte per Fallschirm an Eurem Zielort landen. (1 Stunde Abklingzeit)" }
entries[150737] = { ["name"] = "Überquellende Kiste mit Ordensressourcen", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Erhaltet 4000 Ordensressourcen." }
entries[150738] = { ["name"] = "Holz aus der Überwucherung", ["text"] = "Questgegenstand\n\"Robustes, frisch gehacktes Holz von den saftigen Bäumen der Überwucherung.\"" }
entries[150739] = { ["name"] = "Taschenkanone", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man diesen Gefährten beschwört.\nMit Rechtsklick eine Taschenkanone beschwören oder wieder freigeben.\n80 ( 80)" }
entries[150740] = { ["name"] = "Boomiepuppe", ["text"] = "Einzigartig\nBenutzen: Gebt Euren Mondkinküken dieses Spielzeug, damit sie deutlich glücklicher werden. (3 Sek. Abklingzeit)\nBenötigt Mondkinfest\nVerkaufspreis:" }
entries[150741] = { ["name"] = "Dreispitz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)" }
entries[150742] = { ["name"] = "Feindschnitter 0.9", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man diesen Gefährten beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)" }
entries[150743] = { ["name"] = "Späherkarte: Überlebenshelfer für Kalimdor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Findet Flugpunkte und deckt Karten in Kalimdor auf.\n\"Ein umfassendes Sammelwerk über scharfzahnige, krallige, giftige und Horde-zugehörige Bestien.\"" }
entries[150744] = { ["name"] = "Späherkarte: Kalimdor, auf den Spuren der Erdenmutter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Findet Flugpunkte und deckt Karten in Kalimdor auf.\n\"Wie man das Land wieder heilt, nachdem es von den Wahnsinnigen, den Verderbten oder den Unnatürlichen heimgesucht wurde.\"" }
entries[150745] = { ["name"] = "Späherkarte: Feldzug in den Östlichen Königreichen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Findet Flugpunkte und deckt Karten in den Östlichen Königreichen auf.\n\"Eine umfassende Strategie, wie man die Streitkräfte der Allianz in den Östlichen Königreichen im Falle eines vierten Krieges schnell unschädlich macht.\"" }
entries[150746] = { ["name"] = "Späherkarte: Modernisierung der Nachschublinien in den Östlichen Königreichen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Findet Flugpunkte und deckt Karten in den Östlichen Königreichen auf.\n\"Eine proaktive Machbarkeitsstudie zur Umsetzung einer bedarfsorientierten Nachschubprozessstruktur für die Interesseneigner etwaiger Repräsentanzen in den Außenposten der Östlichen Königreiche.\"" }
entries[150747] = { ["name"] = "Schimmernde Phiole", ["text"] = "Einzigartig\nBenutzen: Kombiniert die schimmernde Phiole, die Verderbnis von Constellas und das Mondscheinwasser, um ein mondgeküsstes Gegengift zu erschaffen. (3 Sek. Abklingzeit)\nBenötigt Mondkinfest" }
entries[150748] = { ["name"] = "Verderbnis von Constellas", ["text"] = "Einzigartig\nBenutzen: Kombiniert die schimmernde Phiole, die Verderbnis von Constellas und das Mondscheinwasser, um ein mondgeküsstes Gegengift zu erschaffen. (3 Sek. Abklingzeit)\nBenötigt Mondkinfest" }
entries[150749] = { ["name"] = "Mondscheinwasser", ["text"] = "Einzigartig\nBenutzen: Kombiniert die schimmernde Phiole, die Verderbnis von Constellas und das Mondscheinwasser, um ein mondgeküsstes Gegengift zu erschaffen. (3 Sek. Abklingzeit)\nBenötigt Mondkinfest" }
entries[150750] = { ["name"] = "Mondgeküsstes Gegengift", ["text"] = "Einzigartig\nBenötigt Mondkinfest\n\"Mit nur einem Löffelchen davon lässt sich alles heilen!\"" }
entries[150751] = { ["name"] = "Stachelfrucht", ["text"] = "Questgegenstand\n\"Der Geruch lässt darauf schließen, dass man diese Frucht lieber nicht essen sollte.\"" }
entries[150752] = { ["name"] = "Schwerer Münzbeutel", ["text"] = "Questgegenstand\n\"Gefüllt mit diversen Münzen.\"" }
entries[150753] = { ["name"] = "Verwesender Blutstein", ["text"] = "Questgegenstand\n\"Riecht nach Tod.\"" }
entries[150754] = { ["name"] = "Valjabus Hauerring", ["text"] = "Questgegenstand\n\"Ein primitiver Ring, der unendlich lange im Grab gelegen hat und deswegen angelaufen ist.\"" }
entries[150755] = { ["name"] = "Knochenstaub", ["text"] = "\"Hat zwar keinen praktischen Nutzen, aber vielleicht will ihn ja jemand kaufen.\"\nVerkaufspreis:" }
entries[150756] = { ["name"] = "Gewobene Federhalskette", ["text"] = "\"Diese Halskette besteht aus gewobenen Pflanzenfasern und ist mit den Federn verschiedener Vögel aus dem Sumpf von Nazmir geschmückt.\"\nVerkaufspreis:" }
entries[150757] = { ["name"] = "Gee'daes Hammer", ["text"] = "Questgegenstand\n\"Überraschenderweise hat das raue Klima von Nazmir dem Hammer auch in der langen Zeit nichts anhaben können.\"" }
entries[150759] = { ["name"] = "Regenerierender Balsam", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Trägt eine einzelne Dosis regenerierenden Balsams auf Euer Ziel auf.\n\"Lindert Brandwunden und bietet begrenzten Schutz vor den Elementen.\"" }
entries[150760] = { ["name"] = "Marke zum Rathausausbau", ["text"] = "Herbeigezauberter Gegenstand\n\"Durch das Abschließen von Weltquests könnt Ihr Eure Marke zum Rathausausbau aufwerten, neue Inhalte freischalten und Zugang zum finalen Ziel erhalten.\"" }
