entries[151538] = { ["name"] = "Glyphe 'Funkensplitter'", ["text"] = "Klassen: Hexenmeister\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nAls Zerstörungshexenmeister können Eure Seelensplitter in instabile Funken eingeschlossen sein, die über Eurem Kopf schweben. Exklusiv mit: Glyphe 'Schwebende Splitter' Glyphe 'Teufelsberührte Splitter'\nVerkaufspreis:" }
entries[151539] = { ["name"] = "Technik: Glyphe 'Funkensplitter'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Glyphe 'Funkensplitter' herstellt.\nStellt eine Glyphe 'Funkensplitter' her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nGlyphe 'Funkensplitter'\nKlassen: Hexenmeister\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nAls Zerstörungshexenmeister können Eure Seelensplitter in instabile Funken eingeschlossen sein, die über Eurem Kopf schweben. Exklusiv mit: Glyphe 'Schwebende Splitter' Glyphe 'Teufelsberührte Splitter'\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (15), Rosenrote Pigmente (5)" }
entries[151540] = { ["name"] = "Glyphe 'Schwebende Splitter'", ["text"] = "Klassen: Hexenmeister\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Seelensplitter schweben jetzt über Eurem Kopf. Exklusiv mit: Glyphe 'Funkensplitter' Glyphe 'Teufelsberührte Splitter'\nVerkaufspreis:" }
