entries[151607] = { ["name"] = "Astraler Alchemistenstein", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+ 7 Vielseitigkeit\nAnlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 19 erhöht. Es wird stets Euer höchster Wert gewählt.\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie der Verheerten Inseln\n(1)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:" }
entries[151608] = { ["name"] = "Lichtblutelixier", ["text"] = "Benutzen: Erfüllt den Spielercharakter mit Lichtenergie, durch die er Dämonen manchmal zusätzlichen Schaden zufügt. Hält 30 Min. lang an.\n\nKann nur im Freien auf den Verheerten Inseln und Argus verwendet werden. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[151609] = { ["name"] = "Tränen der Naaru", ["text"] = "Benutzen: Zeigt 30 Min. lang den Aufenthaltsort aller in der Nähe befindlichen Dämonen auf der Minikarte an. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[151610] = { ["name"] = "Vantusrune: Antorus, der Brennende Thron", ["text"] = "Benutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus Antorus, dem Brennenden Thron, ein, was Eure Vielseitigkeit um 3380 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\nIhr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis:" }
