entries[151614] = { ["name"] = "Rüstungsschutz für abgenutzte Erbstücke", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Wertet Erbstückrüstungen, Schmuckstücke oder Gegenstände für die Schildhand auf, sodass sie bis Stufe 45 aufsteigen können.\n\nFunktioniert nur bei Erbstücken, die auf Stufe 40 aufsteigen können." }
