entries[151617] = { ["name"] = "Abfangjäger von Orgrimmar", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Abfangjäger von Orgrimmar oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Durch eine nach vorne gerichtete Kanone in Form eines Wolfskopfs ist dieser Jagdflieger besonders gut für Luftkämpfe geeignet.\"\nBlizzCon 2017" }
entries[151618] = { ["name"] = "Himmelsjäger von Sturmwind", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Himmelsjäger von Sturmwind oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Gebt mir so viele Motoren, wie Ihr habt.\" - Ingenieur Zahnrad\nBlizzCon 2017" }
