entries[151623] = { ["name"] = "Luzider Alptraum", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren luziden Alptraum oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Auf diesem Reittier wandern Eure Gedanken oft zu weit entfernten Orten.\"\nBeute von:\nVerlangen des Rätslers" }
entries[151624] = { ["name"] = "Y'meras Arkanokristall", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Stabilisiert eine instabile Energieleitung. (5 Sek. Abklingzeit)" }
entries[151625] = { ["name"] = "Rubinroter Qirajiresonanzkristall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 7 tagen\nReittier\n(Accountweit)\nBenutzen: Beschwört eine reitbare rote Qirajikriegsdrohne oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\"Wenn der Ruf des Skarabäus endet, kehren die Qiraji in ihre Baue zurück.\"\nVerkaufspreis:\n\"Während des Rufs des Skarabäus wurde kürzlich eine Qirajikriegsdrohne gesehen. Könnte das darauf hindeuten, dass diese tödlichen Kreaturen an die Oberfläche zurückkehren?\"\nWeltereignis:\nRuf des Skarabäus" }
entries[151626] = { ["name"] = "Saphirblauer Qirajiresonanzkristall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 7 tagen\nReittier\n(Accountweit)\nBenutzen: Beschwört eine reitbare blaue Qirajikriegsdrohne oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\"Wenn der Ruf des Skarabäus endet, kehren die Qiraji in ihre Baue zurück.\"\nVerkaufspreis:\n\"Während des Rufs des Skarabäus wurde kürzlich eine Qirajikriegsdrohne gesehen. Könnte das darauf hindeuten, dass diese tödlichen Kreaturen an die Oberfläche zurückkehren?\"\nWeltereignis:\nRuf des Skarabäus" }
entries[151627] = { ["name"] = "Klumpiges Krabbenfleisch", ["text"] = "Questgegenstand\n\"Vollgesogen mit Salzwasser.\"" }
entries[151628] = { ["name"] = "Seefahrerhut", ["text"] = "Questgegenstand\n\"Verwittert und abgegriffen, aber immer noch gediegen.\"" }
entries[151629] = { ["name"] = "Nautische Karte", ["text"] = "Questgegenstand\n\"Zeigt Strömungen und Tiefen im Meer an.\"" }
entries[151630] = { ["name"] = "Gesprungener Kompass", ["text"] = "Questgegenstand\n\"Die Nadel wirkt ein bisschen brüchig.\"" }
entries[151631] = { ["name"] = "Verwittertes Fernrohr", ["text"] = "Questgegenstand\n\"Die Linse ist trüb und zerkratzt.\"" }
entries[151632] = { ["name"] = "Bergbauaffe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)" }
entries[151633] = { ["name"] = "Grubenratte", ["text"] = "Wird beim Anlegen gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)" }
entries[151634] = { ["name"] = "Schlachtcape der Eredar", ["text"] = "Wird beim Aufheben gebunden\nRücken\n3 Rüstung\n+3 [Beweglichkeit oder Stärke oder Intelligenz]\n+4 Ausdauer\n+ 3 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 3.\nVerkaufspreis:" }
entries[151635] = { ["name"] = "Adelsschleier der Eredar", ["text"] = "Wird beim Aufheben gebunden\nRücken\n3 Rüstung\n+3 [Beweglichkeit oder Stärke oder Intelligenz]\n+4 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 2.\nVerkaufspreis:" }
entries[151636] = { ["name"] = "Seele des Erzdruiden", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\n\nPrismatischer Sockel\n\nKlassen: Druide\nAnlegen: Erhaltet das Talent 'Seele des Waldes'.\n\"Der Zirkel des Cenarius ist im Hain der Träume zu finden. Sie sind die Hüter der Natur, die Bewahrer des Gleichgewichts und die Beschützer allen Lebens.\"\nVerkaufspreis:" }
entries[151638] = { ["name"] = "Verseuchter Beutel mit Haustierbedarf", ["text"] = "Wird beim Aufheben gebunden\n\"Teile dieses Beutels zerfallen.\"\n<Zum Öffnen rechtsklicken>" }
entries[151639] = { ["name"] = "Seele des Rächers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 4.\n\nPrismatischer Sockel\n\nKlassen: Dämonenjäger\nAnlegen: Erhaltet je nach Spezialisierung eins der folgenden Talente:\n\nVerwüstung Erstes Blutvergießen\nRachsucht: Kollateralschaden\n\"Die Illidari sind in der Teufelshammer zu finden. Sie kontrollieren die verbotenen Kräfte der Dämonen, die sie vernichten, um damit die Mächte des Chaos zu bekämpfen – und dabei scheuen sie vor nichts zurück.\"\nVerkaufspreis:" }
entries[151640] = { ["name"] = "Seele des Todesgebieters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 4.\n\nPrismatischer Sockel\n\nKlassen: Todesritter\nAnlegen: Erhaltet je nach Spezialisierung eins der folgenden Talente:\n\nBlut: 'Übles Bollwerk'\nFrost: 'Aufziehender Sturm'\nUnheilig: 'Platzende Geschwüre'\n\"Die Ritter der Schwarzen Klinge sind in Acherus, der Schwarzen Festung, zu finden. Einst waren sie die Champions der Geißel. Nun sind sie die Verdammten.\"\nVerkaufspreis:" }
entries[151641] = { ["name"] = "Seele des Meisterjägers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 4.\n\nPrismatischer Sockel\n\nKlassen: Jäger\nAnlegen: Erhaltet je nach Spezialisierung eins der folgenden Talente:\n\nTierherrschaft: 'Jagdfieber'\nTreffsicherheit: 'Sichern und Laden'\nÜberleben: 'Viperngift'\n\"Der Unsichtbare Pfad ist in der Volltrefferhütte zu finden. Sie sind die Augen in der Wildnis. Sie sind die Schwingen im Wind. Sie beschreiten den einsamen Weg.\"\nVerkaufspreis:" }
entries[151642] = { ["name"] = "Seele des Erzmagiers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 5.\nErhöht Eure Meisterschaftswertung um + 4.\n\nPrismatischer Sockel\n\nKlassen: Magier\nAnlegen: Erhaltet je nach Spezialisierung eins der folgenden Talente:\n\nArkan: 'Amplifikation'\nFeuer: 'Flammeninferno'\nFrost: 'Eiskalte Berührung'\n\"Die Tirisgarde ist in der Halle des Wächters zu finden. Sie besteht aus Elitemagierwachen von Dalaran, die schon früher dem Ruf des Rats von Tirisfal folgten, um in Abwesenheit des Wächters Schlachten zu schlagen.\"\nVerkaufspreis:" }
entries[151643] = { ["name"] = "Seele des Großmeisters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 5.\n\nPrismatischer Sockel\n\nKlassen: Mönch\nAnlegen: Erhaltet je nach Spezialisierung eins der folgenden Talente:\n\nBraumeister: 'Nehmerqualitäten'\nNebelwirker: 'Nebelhülle'\nWindläufer: 'Auge des Tigers'\n\"Der Orden des Verheerten Tempels ist im Tempel der Fünf Sonnenaufgänge zu finden. Er trägt die Strahlen der Hoffnung in eine scheinbar düstere Zukunft.\"\nVerkaufspreis:" }
entries[151644] = { ["name"] = "Seele des Hochlords", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 4.\n\nPrismatischer Sockel\n\nKlassen: Paladin\nAnlegen: Erhaltet je nach Spezialisierung eins der folgenden Talente:\n\nHeilig: 'Göttliche Bestimmung'\nSchutz: 'Heiliger Schild'\nVergeltung: 'Göttliche Bestimmung'\n\"Der Orden der Silbernen Hand ist im Sanktum des Lichts zu finden. Er repräsentiert die geeinte Macht des Argentumkreuzzugs, der Hand von Argus, der Sonnenläufer und der Blutritter.\"\nVerkaufspreis:" }
entries[151645] = { ["name"] = "Modell 8U-DD-L3R", ["text"] = "Benutzen: Lehrt Euch, wie man Buddler beschwört und wieder freigibt.\nMit Rechtsklick Buddler beschwören oder wieder freigeben.\n80 ( 80)" }
entries[151646] = { ["name"] = "Seele des Hohepriesters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 2.\n\nPrismatischer Sockel\n\nKlassen: Priester\nAnlegen: Erhaltet je nach Spezialisierung eins der folgenden Talente:\n\nDisziplin: 'Schicksalshafte Wendung'\nHeilig: 'Woge des Lichts'\nSchatten: 'Schicksalshafte Wendung'\n\"Die Konklave ist im Netherlichttempel zu finden. Sie sind die Meister des Lichts und öffnen sich der Leere – denn ohne Dunkelheit gibt es kein Licht und ohne Licht keine Dunkelheit.\"\nVerkaufspreis:" }
entries[151647] = { ["name"] = "Seele des Scharfsehers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 5.\n\nPrismatischer Sockel\n\nKlassen: Schamane\nAnlegen: Erhaltet je nach Spezialisierung eins der folgenden Talente:\n\nElementar: Echo der Elemente\nVerstärkung: Erdrutsch\nWiederherstellung: Echo der Elemente\n\"Der Irdene Ring ist im Herzen von Azeroth zu finden. Sie sind in der Lage, die mächtigen elementaren Kräfte zu bändigen und halten sie im Gleichgewicht. Sie sind die wahren Meister der Elemente.\"\nVerkaufspreis:" }
entries[151648] = { ["name"] = "Geschwollene Raptorteile", ["text"] = "Questgegenstand\n\"Tortollaner müssen widerstandsfähige Mägen haben, wenn Kajosh bereit ist, rohes Raptorfleisch zu essen.\"" }
entries[151649] = { ["name"] = "Seele des Netherfürsten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\n\nPrismatischer Sockel\n\nKlassen: Hexenmeister\nAnlegen: Erhaltet je nach Spezialisierung eins der folgenden Talente:\n\nGebrechen: 'Seelenverbindung'\nDämonologie: 'Seelenverbindung'\nZerstörung: 'Ausrottung'\n\"Der Rat der Schwarzen Ernte ist in der Schreckensnarbe zu finden. Sie sind die Ernter der Seelen, Feldherren ganzer Dämonenscharen und Meister der dunklen Künste.\"\nVerkaufspreis:" }
entries[151650] = { ["name"] = "Seele des Schlachtenfürsten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 4.\n\nPrismatischer Sockel\n\nKlassen: Krieger\nAnlegen: Erhaltet je nach Spezialisierung eins der folgenden Talente:\n\nWaffen: 'Aggressionsmanagement'\nFuror: 'Massaker'\nSchutz: 'Blutrache'\n\"Die Valarjar sind in der Himmelsfeste zu finden. Sie sind die mächtigen, aufgestiegenen Champions von Odyn, die die Welt vor jeglichem Unheil beschützen.\"\nVerkaufspreis:" }
entries[151651] = { ["name"] = "Gravitationsverringerungspantoffeln", ["text"] = "Benutzen: Bringt die Gravitationsverringerungspantoffeln an Eurem aktuellen Schuhwerk an, um höher springen zu können. Hält 3 Min. lang an.\n\nKann nur im Freien auf den Verheerten Inseln und auf Argus verwendet werden. (15 Min Abklingzeit)" }
entries[151652] = { ["name"] = "Wurmlochgenerator: Argus", ["text"] = "Wird bei Benutzung gebunden\nSpielzeug\nBenutzen: Teleportiert den Spielercharakter an einen zufälligen Ort auf Argus. (15 Min Abklingzeit)\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\n\"Der Benutzer ist für die letztendlichen Teleportationszielorte allein verantwortlich und nicht berechtigt, rechtliche Schritte gegen den Hersteller dieses Geräts einzuleiten.\"\nVerkaufspreis:" }
entries[151653] = { ["name"] = "Rezeptfetzen von den Verheerten Inseln", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Fügt 10 Rezeptfetzen von den Verheerten Inseln zusammen, um ein Kochrezept zu erhalten, das Ihr noch nicht entdeckt habt." }
entries[151654] = { ["name"] = "Vantusrunentechnik: Antorus, der Brennende Thron", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Vantusrune: Antorus, der Brennende Thron herstellt.\nErschafft eine Vantusrune: Antorus, der Brennende Thron.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nVantusrune: Antorus, der Brennende Thron\nBenutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus Antorus, dem Brennenden Thron, ein, was Eure Vielseitigkeit um 3380 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\nIhr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis:\nBenötigt Fahle Pigmente (10), Rosenrote Pigmente (30)" }
entries[151655] = { ["name"] = "Vantusrunentechnik: Antorus, der Brennende Thron", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Vantusrune: Antorus, der Brennende Thron effizienter herstellt.\nVerringert die erforderlichen Materialien zur Herstellung einer Vantusrune: Antorus, der Brennende Thron.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nVantusrune: Antorus, der Brennende Thron\nBenutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus Antorus, dem Brennenden Thron, ein, was Eure Vielseitigkeit um 3380 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\nIhr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis:\nBenötigt Fahle Pigmente (8), Rosenrote Pigmente (30)" }
entries[151656] = { ["name"] = "Vantusrunentechnik: Antorus, der Brennende Thron", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Vantusrune: Antorus, der Brennende Thron effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung einer Vantusrune: Antorus, der Brennende Thron.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nVantusrune: Antorus, der Brennende Thron\nBenutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus Antorus, dem Brennenden Thron, ein, was Eure Vielseitigkeit um 3380 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\nIhr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis:\nBenötigt Fahle Pigmente (6), Rosenrote Pigmente (30)" }
entries[151657] = { ["name"] = "Rezept: Lichtblutelixier", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Lichtblutelixier herstellt.\nStellt ein Lichtblutelixier her.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nLichtblutelixier\nBenutzen: Erfüllt den Spielercharakter mit Lichtenergie, durch die er Dämonen manchmal zusätzlichen Schaden zufügt. Hält 30 Min. lang an.\n\nKann nur im Freien auf den Verheerten Inseln und Argus verwendet werden. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Astralwinde (25), Ursargerit , Kristallphiole" }
entries[151658] = { ["name"] = "Rezept: Lichtblutelixier", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Lichtblutelixier effizienter herstellt.\nStellt ein Lichtblutelixier effizienter her.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nLichtblutelixier\nBenutzen: Erfüllt den Spielercharakter mit Lichtenergie, durch die er Dämonen manchmal zusätzlichen Schaden zufügt. Hält 30 Min. lang an.\n\nKann nur im Freien auf den Verheerten Inseln und Argus verwendet werden. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Astralwinde (20), Kristallphiole" }
entries[151659] = { ["name"] = "Rezept: Lichtblutelixier", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Lichtblutelixier noch effizienter herstellt, und gewährt eine Chance auf die Herstellung mehrerer Tränke.\nChance auf die Herstellung mehrerer Tränke.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nLichtblutelixier\nBenutzen: Erfüllt den Spielercharakter mit Lichtenergie, durch die er Dämonen manchmal zusätzlichen Schaden zufügt. Hält 30 Min. lang an.\n\nKann nur im Freien auf den Verheerten Inseln und Argus verwendet werden. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Astralwinde (15), Kristallphiole" }
