entries[151701] = { ["name"] = "Extraktionsanzug", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Zieht eine Aschenwinduniform an, um Euch als Besatzungsmitglied von Aschenwind zu verkleiden, sodass Ihr schwerer zu entdecken seid.\n\nFunktioniert nur in Vol'dun.\n\"Hilft beim Abbau von Azerit.\"" }
entries[151702] = { ["name"] = "Aufgeladener Rissstein", ["text"] = "Wird beim Aufheben gebunden\n\"Gestattet den Zugang zu geringeren Rissen und großen Rissen.\"" }
entries[151703] = { ["name"] = "Rezept: Tränen der Naaru", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man Tränen der Naaru herstellt.\nStellt Tränen der Naaru her.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nTränen der Naaru\nBenutzen: Zeigt 30 Min. lang den Aufenthaltsort aller in der Nähe befindlichen Dämonen auf der Minikarte an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Astralwinde (20), Ursargerit , Kristallphiole" }
entries[151704] = { ["name"] = "Rezept: Tränen der Naaru", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man Tränen der Naaru effizienter herstellt.\nStellt Tränen der Naaru effizienter her.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nTränen der Naaru\nBenutzen: Zeigt 30 Min. lang den Aufenthaltsort aller in der Nähe befindlichen Dämonen auf der Minikarte an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Astralwinde (15), Kristallphiole" }
entries[151705] = { ["name"] = "Rezept: Tränen der Naaru", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man Tränen der Naaru noch effizienter herstellt, und gewährt eine Chance auf die Herstellung mehrerer Tränke.\nChance auf die Herstellung mehrerer Tränke.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nTränen der Naaru\nBenutzen: Zeigt 30 Min. lang den Aufenthaltsort aller in der Nähe befindlichen Dämonen auf der Minikarte an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Astralwinde (10), Kristallphiole" }
entries[151706] = { ["name"] = "Rezept: Astraler Alchemistenstein", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen astralen Alchemistenstein herstellt.\nStellt einen astralen Alchemistenstein her.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nAstraler Alchemistenstein\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+ 7 Vielseitigkeit\nAnlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 19 erhöht. Es wird stets Euer höchster Wert gewählt.\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie der Verheerten Inseln\n(1)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:\nBenötigt Astralwinde (75), Infernaler Alchemistenstein , Ursargerit (5)" }
entries[151707] = { ["name"] = "Rezept: Astraler Alchemistenstein", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen astralen Alchemistenstein effizienter herstellt.\nStellt einen astralen Alchemistenstein effizienter her.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nBenötigt Der Argusvorstoß\n- Respektvoll\nVerkaufspreis:\nAstraler Alchemistenstein\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+ 7 Vielseitigkeit\nAnlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 19 erhöht. Es wird stets Euer höchster Wert gewählt.\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie der Verheerten Inseln\n(1)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:\nBenötigt Astralwinde (60), Infernaler Alchemistenstein , Ursargerit (4)" }
entries[151708] = { ["name"] = "Rezept: Astraler Alchemistenstein", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen astralen Alchemistenstein noch effizienter herstellt.\nStellt einen astralen Alchemistenstein noch effizienter her.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nBenötigt Der Argusvorstoß\n- Ehrfürchtig\nVerkaufspreis:\nAstraler Alchemistenstein\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+ 7 Vielseitigkeit\nAnlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 19 erhöht. Es wird stets Euer höchster Wert gewählt.\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie der Verheerten Inseln\n(1)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:\nBenötigt Astralwinde (50), Infernaler Alchemistenstein , Ursargerit (3)" }
entries[151709] = { ["name"] = "Pläne: Teufelsschieferanker", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Teufelsschieferanker herstellt.\nStellt einen Teufelsschieferanker her.\nBenötigt Schmiedekunst der Verheerten Inseln (1)\n\nTeufelsschieferanker\nBenutzen: Bringt einen Anker an Euren Beinen an, der Euch mit hoher Geschwindigkeit auf den Meeresgrund sinken lässt. Kann nur im Wasser eingesetzt werden. (30 Sek. Abklingzeit)\n\"Schwer genug, um einen Kraken zum Meeresboden zu schicken!\"\nBenötigt Teufelsschiefer (50)" }
entries[151710] = { ["name"] = "Rezept: Ursargerit transmutieren", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man Blut von Sargeras zu Ursargerit transmutiert.\nTransmutiert Blut von Sargeras zu Ursargerit.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nUrsargerit\nWird beim Aufheben gebunden\nHandwerksmaterial\n\"Kann zur Herstellung von Gegenständen der Handwerksberufe verwendet oder bei Händler Caelen an der Obliterumschmiede in Dalaran abgegeben werden.\"\nVerkaufspreis:\nBenötigt Blut von Sargeras (25)" }
entries[151711] = { ["name"] = "Pläne: Empyriumbrustplatte", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Empyriumbrustplatte herstellt.\nStellt eine Empyriumbrustplatte her.\nBenötigt Schmiedekunst der Verheerten Inseln (1)\nVerkaufspreis:\nEmpyriumbrustplatte\nWird beim Anlegen gebunden\nBrust Platte\n18 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nHaltbarkeit 165 / 165\nVerkaufspreis:\nBenötigt Empyrium (125), Ursargerit (10)" }
entries[151712] = { ["name"] = "Pläne: Empyriumbrustplatte", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Empyriumbrustplatte effizienter herstellt.\nVerringert die erforderlichen Materialien zur Herstellung einer Empyriumbrustplatte.\nBenötigt Schmiedekunst der Verheerten Inseln (1)\nBenötigt Armee des Lichts\n- Respektvoll\nVerkaufspreis:\nEmpyriumbrustplatte\nWird beim Anlegen gebunden\nBrust Platte\n18 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nHaltbarkeit 165 / 165\nVerkaufspreis:\nBenötigt Empyrium (110), Ursargerit (7)" }
entries[151713] = { ["name"] = "Pläne: Empyriumbrustplatte", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Empyriumbrustplatte noch effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung einer Empyriumbrustplatte.\nBenötigt Schmiedekunst der Verheerten Inseln (1)\nVerkaufspreis:\nEmpyriumbrustplatte\nWird beim Anlegen gebunden\nBrust Platte\n18 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nHaltbarkeit 165 / 165\nVerkaufspreis:\nBenötigt Empyrium (95), Ursargerit (5)" }
entries[151714] = { ["name"] = "Bauplan: Gravitationsverringerungspantoffeln", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man Gravitationsverringerungspantoffeln herstellt.\nStellt Gravitationsverringerungspantoffeln her.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nGravitationsverringerungspantoffeln\nBenutzen: Bringt die Gravitationsverringerungspantoffeln an Eurem aktuellen Schuhwerk an, um höher springen zu können. Hält 3 Min. lang an.\n\nKann nur im Freien auf den Verheerten Inseln und auf Argus verwendet werden. (15 Min Abklingzeit)\nBenötigt Empyrium (25), Übergroße Sprengkapsel (8), Ursargerit" }
entries[151717] = { ["name"] = "Bauplan: Wurmlochgenerator: Argus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Wurmlochgenerator: Argus herstellt.\nStellt einen Wurmlochgenerator: Argus her.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nWurmlochgenerator: Argus\nWird bei Benutzung gebunden\nSpielzeug\nBenutzen: Teleportiert den Spielercharakter an einen zufälligen Ort auf Argus. (15 Min Abklingzeit)\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\n\"Der Benutzer ist für die letztendlichen Teleportationszielorte allein verantwortlich und nicht berechtigt, rechtliche Schritte gegen den Hersteller dieses Geräts einzuleiten.\"\nVerkaufspreis:\nBenötigt Empyrium (30), Lockerer Abzug (2), Ursargerit (2)" }
